<script setup lang="ts">import type {Run} from '../types/domain';import {colors} from '../constants/enums';defineProps<{run:Run}>();</script><template><div class="plot"><div class="plot-title"><span>客户位置 · 样本散点</span><small>按群分层随机抽样 · 约 180 位</small></div><svg viewBox="0 0 680 300" role="img" aria-label="客户距上次学习天数与累计消费散点图"><g class="grid"><path v-for="x in [80,200,320,440,560]" :key="x" :d="`M${x} 20V260`"/><path v-for="y in [30,85,140,195,250]" :key="y" :d="`M55 ${y}H650`"/></g><text x="10" y="20">消费 ¥</text><text x="510" y="288">距上次学习 / 天 →</text><text x="55" y="280">0</text><text x="570" y="280">100</text><circle v-for="point in run.result.sample||[]" :key="point.code" :cx="55+Math.min(point.recency,115)*5" :cy="255-Math.min(point.spend,2300)/10" r="3.3" :fill="colors[point.label%colors.length]" opacity=".7"><title>{{point.code}} / {{point.spend}}元 / {{point.recency}}天</title></circle></svg></div></template>
